import time

def exponential_retry(max_attempts=3, base_delay=0.1):
    def decorator(func):
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        raise e
                    delay = base_delay * (2 ** (attempts - 1))
                    time.sleep(delay)
        return wrapper
    return decorator
